ADC_InitTypeDef cfg;
ADC_StructInit(&cfg);
cfg.ADC_ExternalTrigConv = ADC_ExternalTrigConv_T3_TRGO;
ADC_Init(ADC1, &cfg);

const uint32_t pair = ADC_GetDualModeConversionValue();
const uint16_t adc1 = (uint16_t)pair;
const uint16_t adc2 = (uint16_t)(pair >> 16);
(void)adc1;
(void)adc2;

static uint16_t samples[16];
DMA_InitTypeDef cfg;
DMA_StructInit(&cfg);
cfg.DMA_PeripheralBaseAddr = (uint32_t)&ADC1->DR;
cfg.DMA_MemoryBaseAddr = (uint32_t)samples;
cfg.DMA_BufferSize = 16u;
cfg.DMA_MemoryInc = DMA_MemoryInc_Enable;
cfg.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;
cfg.DMA_MemoryDataSize = DMA_MemoryDataSize_HalfWord;
DMA_Init(DMA1_Channel1, &cfg);
